import type { ReactElement } from 'react';
import './StatusList.css';
import type { Status, StatusItem } from '../../types';

export const STATUS_LABELS: Record<Status, string> = {
  todo: 'To Do',
  'in-progress': 'In Progress',
  done: 'Done',
  blocked: 'Blocked',
};

export const SKELETON_COUNT = 6;

export function statusColor(status: Status): string {
  switch (status) {
    case 'todo':
      return 'status-item-todo';
    case 'in-progress':
      return 'status-item-in-progress';
    case 'done':
      return 'status-item-done';
    case 'blocked':
      return 'status-item-blocked';
  }
}

const STATUS_ORDER: Status[] = ['todo', 'in-progress', 'done', 'blocked'];

interface StatusListProps {
  // null = loading; array (possibly empty) = loaded
  items: StatusItem[] | null;
}

export function StatusList({ items }: StatusListProps): ReactElement {
  if (items === null) {
    return (
      <ul className="status-list" aria-label="Status list">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="skeleton-item">
            <div className="skeleton-line" />
          </li>
        ))}
      </ul>
    );
  }

  const grouped = STATUS_ORDER.reduce<Record<Status, StatusItem[]>>(
    (acc, status) => {
      acc[status] = items.filter((item) => item.status === status);
      return acc;
    },
    { todo: [], 'in-progress': [], done: [], blocked: [] },
  );

  return (
    <div className="status-list" aria-label="Status list">
      {STATUS_ORDER.map((status) => {
        const group = grouped[status];
        if (group.length === 0) {
          return null;
        }
        return (
          <div key={status} className="status-group-container">
            <h2 className="status-group-heading">{STATUS_LABELS[status]}</h2>
            <ul className="status-group">
              {group.map((item) => (
                <li key={item.id} className={`status-item ${statusColor(item.status)}`}>
                  {item.label}
                </li>
              ))}
            </ul>
          </div>
        );
      })}
    </div>
  );
}

