import { useState } from 'react';
import './ChipFilter.css';

type FilterLabel = 'All' | 'Active' | 'Archived' | 'Starred';

const FILTERS: FilterLabel[] = ['All', 'Active', 'Archived', 'Starred'];

interface ChipFilterProps {
  onFilterChange?: (filter: FilterLabel) => void;
}

// Owns only visual pressed state; grid filtering is not wired.
export function ChipFilter({ onFilterChange }: ChipFilterProps): JSX.Element {
  const [pressed, setPressed] = useState<FilterLabel>('All');

  function handleClick(filter: FilterLabel): void {
    setPressed(filter);
    onFilterChange?.(filter);
  }

  return (
    <div className="chip-bar" role="group" aria-label="Filter chips">
      {FILTERS.map((filter) => (
        <button
          key={filter}
          type="button"
          className="chip"
          aria-pressed={pressed === filter}
          onClick={() => handleClick(filter)}
        >
          {filter}
        </button>
      ))}
    </div>
  );
}

