import { useState, useEffect } from 'react';
import type { StatusItem } from '../../types';
import { getTasks } from '../../api';
import './TaskBoard.css';

const SKELETON_COUNT = 5;

export function TaskBoard(): React.JSX.Element {
  // null = loading; array = loaded
  const [tasks, setTasks] = useState<StatusItem[] | null>(null);

  useEffect(() => {
    getTasks().then(setTasks).catch(() => setTasks([]));
  }, []);

  const renderList = (): React.ReactNode => {
    if (tasks === null) {
      return (
        <ul className="task-board-list">
          {Array.from({ length: SKELETON_COUNT }, (_, i) => (
            <li key={i} className="task-board-skeleton-item">
              <span className="task-board-skeleton-text"></span>
            </li>
          ))}
        </ul>
      );
    }
    if (tasks.length === 0) {
      return <p className="task-board-empty">No tasks yet</p>;
    }
    return (
      <ul className="task-board-list">
        {tasks.map((task) => (
          <li key={task.id} className="task-board-item">
            <span className="task-board-item-label">{task.label}</span>
            <span className="task-board-item-status">{task.status}</span>
          </li>
        ))}
      </ul>
    );
  };

  return (
    <section className="task-board">
      <header className="task-board-header">
        <h2 className="task-board-title">Tasks</h2>
        {tasks !== null && (
          <span className="task-board-badge">{tasks.length}</span>
        )}
      </header>
      <div className="task-board-filter-bar"></div>
      <div className="task-board-content">
        {renderList()}
      </div>
    </section>
  );
}

