import './PriceDisplay.css';

interface PriceDisplayProps {
  price: number;
  originalPrice?: number;
  currencySymbol?: string;
}

// Math.ceil: always round up to avoid under-charging
function formatPrice(amount: number, symbol: string): string {
  return `${symbol}${Math.ceil(amount).toFixed(2)}`;
}

export function PriceDisplay({ price, originalPrice, currencySymbol = '$' }: PriceDisplayProps): JSX.Element {
  const hasDiscount = originalPrice !== undefined && originalPrice > price;

  return (
    <span className="price-display">
      <span className="price-display-current" aria-label={`Price: ${formatPrice(price, currencySymbol)}`}>
        {formatPrice(price, currencySymbol)}
      </span>
      {hasDiscount && (
        <s className="price-display-original" aria-label={`Original price: ${formatPrice(originalPrice, currencySymbol)}`}>
          {formatPrice(originalPrice, currencySymbol)}
        </s>
      )}
    </span>
  );
}

