import type { ReactElement } from 'react';
import './ChipBar.css';
import type { Status } from '../../types';

interface ChipBarProps {
  statuses: Status[];
  selected: Set<Status>;
  onSelectionChange: (next: Set<Status>) => void;
}

export function ChipBar({ statuses, selected, onSelectionChange }: ChipBarProps): ReactElement {
  function handleClick(status: Status): void {
    const next = new Set(selected);
    if (next.has(status)) {
      next.delete(status);
    } else {
      next.add(status);
    }
    onSelectionChange(next);
  }

  return (
    <div className="chip-bar" role="toolbar" aria-label="Filter by status">
      {statuses.map((status) => (
        <button
          key={status}
          type="button"
          className="chip"
          aria-pressed={selected.has(status)}
          onClick={() => handleClick(status)}
        >
          {status}
        </button>
      ))}
    </div>
  );
}

