import type { ReactElement } from 'react';
import './BookCard.css';
import type { Book, Status } from '../../types';

export const STATUS_LABELS: Record<Status, string> = {
  todo: 'To Do',
  'in-progress': 'In Progress',
  done: 'Done',
  blocked: 'Blocked',
};

function badgeClass(status: Status): string {
  switch (status) {
    case 'todo':
      return 'book-card-badge book-card-badge-todo';
    case 'in-progress':
      return 'book-card-badge book-card-badge-in-progress';
    case 'done':
      return 'book-card-badge book-card-badge-done';
    case 'blocked':
      return 'book-card-badge book-card-badge-blocked';
  }
}

interface BookCardProps {
  book: Book;
}

export function BookCard({ book }: BookCardProps): ReactElement {
  return (
    <article className="book-card">
      <h2 className="book-card-title">{book.title}</h2>
      <p className="book-card-author">{book.author}</p>
      <span className={badgeClass(book.status)}>{STATUS_LABELS[book.status]}</span>
    </article>
  );
}

